// Edit these values if your IDs or emails change
const cfg = {
  notionVersion: '2022-06-28',
  db: {
    projects: '3664681e-9822-4557-8f3e-d41b0e15cf86',
    suppliers: '2992f6f9-cc5b-4169-81d0-69443999b37e',
    costs: 'f2bdef68-057a-4bc3-aebc-6a8cbf6fdf94',
    summary: 'd4bf2bc5-7b7f-42fa-964d-22cc3a917f84',
    log: 'c868af3f-f354-4b1b-9546-9fcba68f04d1'
  },
  geminiModel: 'gemini-3.8-flash',
  officeEmail: 'emailofimran1992+denise@gmail.com',
  fallbackPmEmail: 'emailofimran1992+steve@gmail.com',
  defaultCurrency: 'USD',
  confidenceThreshold: 0.75,
  freeMailDomains: ['gmail.com', 'googlemail.com', 'outlook.com', 'hotmail.com', 'live.com', 'yahoo.com', 'icloud.com', 'me.com', 'aol.com', 'proton.me'],
  internalDomains: []
};
return $input.all().map((item, i) => ({ json: { ...item.json, cfg }, binary: item.binary, pairedItem: { item: i } }));

const NL = String.fromCharCode(10);
const GEN = { temperature: 0, responseMimeType: 'application/json', responseSchema: { type: 'OBJECT', properties: { is_cost_document: { type: 'BOOLEAN' }, document_type: { type: 'STRING', enum: ['Invoice', 'Receipt', 'Credit Note', 'Statement / Other'] }, supplier_name: { type: 'STRING', nullable: true }, document_reference: { type: 'STRING', nullable: true }, document_date: { type: 'STRING', nullable: true }, due_date: { type: 'STRING', nullable: true }, total_amount: { type: 'NUMBER', nullable: true }, currency: { type: 'STRING', nullable: true }, payment_status: { type: 'STRING', enum: ['Paid', 'Unpaid', 'Unknown'] }, paid_date: { type: 'STRING', nullable: true }, project_hint: { type: 'STRING', nullable: true }, confidence: { type: 'NUMBER' }, notes: { type: 'STRING', nullable: true } }, required: ['is_cost_document', 'document_type', 'payment_status', 'confidence'] } };
const fnv = (s) => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); };
const prompt = (m) => [
  'You read emails sent to a home builder and the invoice or receipt attached to them.',
  'Return ONLY JSON that matches the schema. Never guess: use null when a value is not visible.',
  'Rules:',
  '- total_amount: the final total payable including tax, as a plain number.',
  '- currency: ISO 4217 code. If only a $ sign is shown and the supplier is in the USA, use USD.',
  '- Dates as YYYY-MM-DD. due_date only if shown, or computable from invoice date + stated terms.',
  '- payment_status: Paid if it is a till/card receipt, marked PAID, balance due is 0, or the email says it has been paid; Unpaid if money is still owed; otherwise Unknown. paid_date if stated.',
  '- document_type: Credit Note when it reduces what we owe.',
  '- project_hint: any job name, client surname, site address, PO number or project code (e.g. PRJ-2) on the document or in the email.',
  '- is_cost_document: false for delivery notices, quotes, statements of account or chit-chat.',
  '- confidence 0-1: how sure you are that supplier, reference, date and total are ALL correct.',
  '',
  'EMAIL FROM: ' + m.fromEmail,
  'EMAIL SUBJECT: ' + m.emailSubject,
  'EMAIL BODY:',
  m.emailText
].join(NL);
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const e = items[i].json;
  const bin = items[i].binary || {};
  const fromEmail = ((e.from && e.from.value && e.from.value[0] && e.from.value[0].address) || '').toLowerCase();
  const meta = { cfg: e.cfg, gmailId: e.id, emailSubject: e.subject || '', emailText: String(e.text || '').slice(0, 4000), emailDate: e.date || new Date().toISOString(), fromEmail, sourceEmailUrl: 'https://mail.google.com/mail/u/0/#all/' + e.id };
  const keys = Object.keys(bin).filter(k => { const mt = String(bin[k].mimeType || '').toLowerCase(); return mt === 'application/pdf' || mt.startsWith('image/'); });
  if (keys.length === 0) {
    out.push({ json: { ...meta, hasAttachment: false, fileName: '', mimeType: '', fingerprint: 'body-' + fnv(meta.emailSubject + meta.emailText), geminiBody: { contents: [{ role: 'user', parts: [{ text: prompt(meta) }] }], generationConfig: GEN } }, pairedItem: { item: i } });
    continue;
  }
  for (const k of keys) {
    const buf = await this.helpers.getBinaryDataBuffer(i, k);
    const b64 = buf.toString('base64');
    out.push({ json: { ...meta, hasAttachment: true, fileName: bin[k].fileName || (k + '.pdf'), mimeType: bin[k].mimeType, fingerprint: fnv(b64) + '-' + buf.length, geminiBody: { contents: [{ role: 'user', parts: [{ text: prompt(meta) }, { inline_data: { mime_type: bin[k].mimeType, data: b64 } }] }], generationConfig: GEN } }, binary: { document: bin[k] }, pairedItem: { item: i } });
  }
}
return out;

const src = $('Split attachments').item;
const s = src.json;
const reasons = [];
let ai = {};
let aiError = null;
try {
  if ($json.error) throw new Error(typeof $json.error === 'string' ? $json.error : JSON.stringify($json.error).slice(0, 300));
  const parts = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts) || [];
  ai = JSON.parse(parts.map(p => p.text || '').join(''));
} catch (err) { aiError = 'AI extraction failed: ' + err.message; ai = {}; }
const isDate = v => typeof v === 'string' && v.length === 10 && !isNaN(Date.parse(v));
const docDate = isDate(ai.document_date) ? ai.document_date : null;
const dueDate = isDate(ai.due_date) ? ai.due_date : null;
const paidDate = isDate(ai.paid_date) ? ai.paid_date : null;
let amount = null;
if (ai.total_amount !== null && ai.total_amount !== undefined && ai.total_amount !== '') { const n = Number(String(ai.total_amount).replace(/[^0-9.-]/g, '')); amount = isFinite(n) ? Math.round(n * 100) / 100 : null; }
const docTypes = ['Invoice', 'Receipt', 'Credit Note', 'Statement / Other'];
const docType = docTypes.includes(ai.document_type) ? ai.document_type : 'Statement / Other';
if (docType === 'Credit Note' && amount !== null && amount > 0) amount = -amount;
let currency = String(ai.currency || '').toUpperCase().trim();
if (!currency) { currency = s.cfg.defaultCurrency; if (!aiError) reasons.push('Currency not stated'); }
else if (!['USD', 'CAD', 'EUR', 'GBP', 'AUD'].includes(currency)) currency = 'Other';
let paymentStatus = ['Paid', 'Unpaid', 'Unknown'].includes(ai.payment_status) ? ai.payment_status : 'Unknown';
if (docType === 'Receipt' && paymentStatus === 'Unknown') paymentStatus = 'Paid';
const confidence = typeof ai.confidence === 'number' ? Math.max(0, Math.min(1, ai.confidence)) : 0;
const isCost = aiError ? true : ai.is_cost_document !== false;
if (aiError || confidence < s.cfg.confidenceThreshold) reasons.push('Low AI confidence');
if (isCost && amount === null) reasons.push('Amount unclear');
const monthFrom = docDate || String(s.emailDate).slice(0, 10);
const costMonth = isDate(monthFrom) ? monthFrom.slice(0, 7) : new Date().toISOString().slice(0, 7);
const ref = ai.document_reference ? String(ai.document_reference).trim() : '';
const normRef = ref.toLowerCase().replace(/[^a-z0-9]/g, '');
const { geminiBody, ...meta } = s;
return { json: { ...meta, ai, aiError, isCost, docType, supplierNameAI: ai.supplier_name || '', ref, normRef, docDate, dueDate, paidDate, amount, currency, paymentStatus, confidence, costMonth, reviewReasons: reasons }, binary: src.binary };

const d = $('Parse AI output').item.json;
const cfg = d.cfg;
const projects = $('Notion: query projects').item.json.results || [];
const suppliers = $json.results || [];
const plain = arr => (arr || []).map(t => t.plain_text || '').join('');
const prop = (page, name) => (page.properties && page.properties[name]) || {};
const STOP = ['llc', 'inc', 'ltd', 'co', 'corp', 'company', 'the', 'and'];
const norm = v => String(v || '').toLowerCase().split(/[^a-z0-9]+/).filter(w => w && !STOP.includes(w)).join('');
const reasons = [...d.reviewReasons];
let fileUploadId = null;
if (d.hasAttachment) { try { const sent = $('Notion: send file').item.json; if (sent && sent.status === 'uploaded') fileUploadId = sent.id; } catch (e) {} }
// project: 1) PRJ code, 2) keywords or site address
const hay = [d.emailSubject, d.emailText, d.ai.project_hint, d.fileName].join(' ').toLowerCase();
let project = null;
let projectHow = 'not found';
const m = hay.match(/prj[^0-9a-z]{0,3}0*([0-9]+)/);
if (m) { project = projects.find(p => prop(p, 'Project Code').unique_id && prop(p, 'Project Code').unique_id.number === Number(m[1])) || null; if (project) projectHow = 'project code PRJ-' + m[1]; }
if (!project) {
  const hits = projects.filter(p => {
    const kws = plain(prop(p, 'Match Keywords').rich_text).split(/[,;]/).map(x => x.trim().toLowerCase()).filter(x => x.length >= 4);
    const addr = plain(prop(p, 'Site Address').rich_text).toLowerCase();
    return kws.some(k => hay.includes(k)) || (addr.length >= 6 && hay.includes(addr));
  });
  if (hits.length === 1) { project = hits[0]; projectHow = 'keyword match'; }
  else if (hits.length > 1) projectHow = 'ambiguous: ' + hits.map(h => plain(prop(h, 'Project').title)).join(' / ');
}
if (!project && d.isCost) reasons.push('Project not identified');
const pmEmails = project ? ((prop(project, 'PM Email').rollup && prop(project, 'PM Email').rollup.array) || []).map(x => x.email).filter(Boolean) : [];
// supplier: 1) name on document, 2) sender email domain
const senderDomain = (d.fromEmail.split('@')[1] || '').toLowerCase();
const aiName = norm(d.supplierNameAI);
let supplier = null;
let supplierHow = 'not found';
if (aiName.length >= 3) { supplier = suppliers.find(s => { const n = norm(plain(prop(s, 'Name').title)); return n && (n === aiName || n.includes(aiName) || aiName.includes(n)); }) || null; if (supplier) supplierHow = 'name'; }
if (!supplier && senderDomain && !cfg.freeMailDomains.includes(senderDomain) && !cfg.internalDomains.includes(senderDomain)) { supplier = suppliers.find(s => plain(prop(s, 'Email Domain').rich_text).trim().toLowerCase() === senderDomain) || null; if (supplier) supplierHow = 'email domain'; }
const supplierName = supplier ? plain(prop(supplier, 'Name').title) : (d.supplierNameAI || senderDomain || 'Unknown supplier');
if (!supplier && d.isCost) reasons.push('New / unknown supplier');
return { json: { ...d, fileUploadId, projectId: project ? project.id : null, projectName: project ? plain(prop(project, 'Project').title) : '', projectHow, pmEmail: pmEmails[0] || '', supplierId: supplier ? supplier.id : '', supplierName, supplierHow, senderDomain, reviewReasons: [...new Set(reasons)] } };

const STOP = ['llc', 'inc', 'ltd', 'co', 'corp', 'company', 'the', 'and'];
const norm = v => String(v || '').toLowerCase().split(/[^a-z0-9]+/).filter(w => w && !STOP.includes(w)).join('');
let d;
if ($json.object === 'page' && $json.parent) {
  d = { ...$('Match project & supplier').item.json, supplierId: $json.id, supplierHow: 'created new supplier (unverified)' };
} else if ($json.error) {
  d = { ...$('Match project & supplier').item.json, supplierId: '', supplierHow: 'supplier create failed: ' + String($json.error.message || JSON.stringify($json.error)).slice(0, 150) };
} else {
  d = { ...$json };
}
const refPart = d.normRef || ((d.docDate || 'nodate') + '-' + (d.amount === null ? 'noamt' : d.amount));
d.dedupeKey = norm(d.supplierName) + '|' + refPart;
return { json: d };

const d = $('Supplier resolved').item.json;
const cfg = d.cfg;
const plain = arr => (arr || []).map(t => t.plain_text || '').join('');
const rt = v => ({ rich_text: v ? [{ text: { content: String(v).slice(0, 1900) } }] : [] });
const dt = v => ({ date: v ? { start: v } : null });
const today = new Date().toISOString().slice(0, 10);
const live = ($json.results || []).filter(p => { const st = p.properties['Review Status'] && p.properties['Review Status'].status; return !(st && st.name === 'Rejected / Duplicate'); });
const existing = live.find(p => plain(p.properties['Dedupe Key'].rich_text) === d.dedupeKey) || live[0] || null;
let reasons = [...d.reviewReasons];
let action, resultLabel, payload = null, pageId = null;
let finalAmount = d.amount, finalPaymentStatus = d.paymentStatus, finalReviewStatus = reasons.length ? 'Needs Review' : 'Recorded';
let bucket = { supplierId: d.supplierId, supplierName: d.supplierName, costMonth: d.costMonth, currency: d.currency };
if (!d.isCost && !existing) {
  action = 'skip'; resultLabel = 'Skipped - not a cost';
} else if (!existing) {
  action = 'create'; resultLabel = reasons.length ? 'Needs review' : 'Created';
  const props = {
    'Cost': { title: [{ text: { content: (d.supplierName + ' - ' + (d.ref || 'no ref')).slice(0, 200) } }] },
    'Project': { relation: d.projectId ? [{ id: d.projectId }] : [] },
    'Supplier': { relation: d.supplierId ? [{ id: d.supplierId }] : [] },
    'Supplier Name (as written)': rt(d.supplierNameAI),
    'Document Type': { select: { name: d.docType } },
    'Document Ref': rt(d.ref),
    'Document Date': dt(d.docDate),
    'Due Date': dt(d.dueDate),
    'Amount': { number: d.amount },
    'Currency': { select: { name: d.currency } },
    'Payment Status': { select: { name: d.paymentStatus } },
    'Paid Date': dt(d.paymentStatus === 'Paid' ? (d.paidDate || d.docDate || today) : null),
    'Cost Month': rt(d.costMonth),
    'Review Status': { status: { name: finalReviewStatus } },
    'Review Reasons': { multi_select: reasons.map(name => ({ name })) },
    'Submitted By': { email: d.fromEmail || null },
    'Email Subject': rt(d.emailSubject),
    'Email Message ID': rt(d.gmailId),
    'Dedupe Key': rt(d.dedupeKey),
    'File Fingerprint': rt(d.fingerprint),
    'Submission Count': { number: 1 },
    'AI Confidence': { number: d.confidence },
    'Source Email': { url: d.sourceEmailUrl },
    'Notes': rt(['Project: ' + d.projectHow, 'Supplier: ' + d.supplierHow, d.aiError, d.ai.notes].filter(Boolean).join(' | '))
  };
  if (d.fileUploadId) props['Document'] = { files: [{ type: 'file_upload', file_upload: { id: d.fileUploadId }, name: String(d.fileName || 'document').slice(0, 100) }] };
  payload = { parent: { database_id: cfg.db.costs }, properties: props };
} else {
  pageId = existing.id;
  const ep = existing.properties;
  const oldAmount = ep['Amount'].number;
  const oldPay = ep['Payment Status'].select ? ep['Payment Status'].select.name : 'Unknown';
  const oldReview = ep['Review Status'].status ? ep['Review Status'].status.name : 'Recorded';
  const count = (ep['Submission Count'].number || 1) + 1;
  const oldNotes = plain(ep['Notes'].rich_text);
  const amountChanged = d.amount !== null && oldAmount !== null && Math.abs(d.amount - oldAmount) >= 0.01;
  const nowPaid = d.paymentStatus === 'Paid' && oldPay !== 'Paid';
  bucket = { supplierId: (ep['Supplier'].relation[0] && ep['Supplier'].relation[0].id) || d.supplierId, supplierName: d.supplierName, costMonth: plain(ep['Cost Month'].rich_text) || d.costMonth, currency: (ep['Currency'].select && ep['Currency'].select.name) || d.currency };
  if (!d.projectId) { d.projectName = '(project as on existing record)'; d.projectHow = 'existing record'; }
  finalAmount = oldAmount; finalPaymentStatus = oldPay; finalReviewStatus = oldReview;
  if (amountChanged) {
    action = 'update'; resultLabel = 'Updated - amount changed';
    reasons = [...new Set([...(ep['Review Reasons'].multi_select || []).map(o => o.name), ...reasons, 'Amount changed on resubmission'])];
    finalAmount = d.amount; finalReviewStatus = 'Needs Review';
    const props = { 'Amount': { number: d.amount }, 'Review Status': { status: { name: 'Needs Review' } }, 'Review Reasons': { multi_select: reasons.map(name => ({ name })) }, 'Submission Count': { number: count }, 'Email Message ID': rt(d.gmailId), 'Notes': rt([oldNotes, today + ': amount changed ' + oldAmount + ' -> ' + d.amount + ' (from ' + d.fromEmail + ')'].filter(Boolean).join(' | ')) };
    if (d.dueDate) props['Due Date'] = dt(d.dueDate);
    if (nowPaid) { props['Payment Status'] = { select: { name: 'Paid' } }; props['Paid Date'] = dt(d.paidDate || today); finalPaymentStatus = 'Paid'; }
    payload = { properties: props };
  } else if (nowPaid) {
    action = 'update'; resultLabel = 'Updated - payment status'; finalPaymentStatus = 'Paid'; reasons = [];
    payload = { properties: { 'Payment Status': { select: { name: 'Paid' } }, 'Paid Date': dt(d.paidDate || today), 'Submission Count': { number: count }, 'Email Message ID': rt(d.gmailId), 'Notes': rt([oldNotes, today + ': marked Paid (email from ' + d.fromEmail + ')'].filter(Boolean).join(' | ')) } };
  } else {
    action = 'duplicate'; resultLabel = 'Duplicate ignored'; reasons = [];
    payload = { properties: { 'Submission Count': { number: count } } };
  }
}
return { json: { ...d, action, resultLabel, pageId, payload, existingUrl: existing ? existing.url : '', finalAmount, finalPaymentStatus, finalReviewStatus, bucket, reviewReasons: reasons } };

const d = $('Decide action').item.json;
const w = $json;
const writeError = w.error ? String(w.error.message || JSON.stringify(w.error)).slice(0, 300) : null;
const costPageId = (!writeError && w.id) ? w.id : d.pageId;
const costPageUrl = (!writeError && w.url) ? w.url : d.existingUrl;
const b = d.bucket;
return { json: { ...d, costPageId, costPageUrl, writeError, summaryKey: b.supplierId + '|' + b.costMonth + '|' + b.currency } };

const d = $('Summary bucket').item.json;
const seen = new Set();
const ids = [];
let paid = 0;
let unpaid = 0;
const add = (id, review, pay, amt) => { if (!id || seen.has(id)) return; seen.add(id); if (review === 'Rejected / Duplicate') return; ids.push(id); if (pay === 'Paid') paid += amt; else unpaid += amt; };
// count the record just written first, with its new values (guards against Notion query lag)
if (!d.writeError) add(d.costPageId, d.finalReviewStatus, d.finalPaymentStatus, Number(d.finalAmount) || 0);
for (const p of ($json.results || [])) {
  const pr = p.properties;
  add(p.id, pr['Review Status'].status ? pr['Review Status'].status.name : '', pr['Payment Status'].select ? pr['Payment Status'].select.name : '', Number(pr['Amount'].number) || 0);
}
const r2 = v => Math.round(v * 100) / 100;
return { json: { ...d, totalPaid: r2(paid), totalUnpaid: r2(unpaid), costCount: ids.length, costIds: ids, bucketQueryError: $json.error ? 'bucket query failed' : null } };

const s = $('Sum bucket').item.json;
const b = s.bucket;
const found = ($json.results || [])[0] || null;
const props = { 'Total Paid': { number: s.totalPaid }, 'Total Unpaid': { number: s.totalUnpaid }, 'Cost Count': { number: s.costCount }, 'Last Recalculated': { date: { start: new Date().toISOString() } }, 'Costs': { relation: s.costIds.slice(0, 100).map(id => ({ id })) } };
if (found) return { json: { ...s, summaryExists: true, summaryId: found.id, summaryUrl: found.url, summaryBody: { properties: props } } };
props['Summary'] = { title: [{ text: { content: b.supplierName + ' - ' + b.costMonth + ' - ' + b.currency } }] };
props['Summary Key'] = { rich_text: [{ text: { content: s.summaryKey } }] };
props['Supplier'] = { relation: b.supplierId ? [{ id: b.supplierId }] : [] };
props['Month'] = { rich_text: [{ text: { content: b.costMonth } }] };
props['Month Start'] = { date: { start: b.costMonth + '-01' } };
props['Currency'] = { select: { name: b.currency } };
return { json: { ...s, summaryExists: false, summaryId: null, summaryBody: { parent: { database_id: s.cfg.db.summary }, properties: props } } };

const s = $('Prepare summary upsert').item.json;
const NL = String.fromCharCode(10);
const reasons = s.reviewReasons || [];
const needsReview = reasons.length > 0 || !!s.writeError;
const to = [...new Set([needsReview ? s.cfg.officeEmail : null, s.pmEmail || s.cfg.fallbackPmEmail].filter(Boolean))].join(',');
const money = v => (v === null || v === undefined || v === '') ? 'n/a' : Number(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const subject = (needsReview ? '[ACTION NEEDED] ' : '') + 'Cost ' + s.resultLabel.toLowerCase() + ': ' + s.supplierName + ' ' + (s.ref || '') + ' - ' + s.bucket.currency + ' ' + money(s.finalAmount) + ' - ' + (s.projectName || 'project not identified');
const lines = [
  'Result: ' + s.resultLabel,
  'Project: ' + (s.projectName || 'NOT IDENTIFIED') + ' (' + s.projectHow + ')',
  'Supplier: ' + s.supplierName + ' (' + s.supplierHow + ')',
  'Document: ' + s.docType + ' ' + (s.ref || '(no ref)') + ', dated ' + (s.docDate || 'n/a'),
  'Amount: ' + s.bucket.currency + ' ' + money(s.finalAmount) + ' | Payment: ' + s.finalPaymentStatus + (s.dueDate ? ' | Due ' + s.dueDate : ''),
  reasons.length ? 'NEEDS REVIEW: ' + reasons.join(', ') : 'No review needed.',
  s.writeError ? 'WRITE ERROR: ' + s.writeError : null,
  $json.error ? 'Summary update failed - re-run the execution.' : null,
  'Supplier month ' + s.bucket.costMonth + ' (' + s.bucket.currency + '): paid ' + money(s.totalPaid) + ' | unpaid ' + money(s.totalUnpaid) + ' | ' + s.costCount + ' documents',
  'Open in Notion: ' + (s.costPageUrl || 'n/a'),
  'Original email: ' + s.sourceEmailUrl
].filter(x => x !== null);
return { json: { ...s, to, subject, body: lines.join(NL) } };

const d = $('Decide action').item.json;
let notified = '';
let costId = d.pageId || null;
let writeError = null;
let summaryLine = '';
try { notified = $('Build notification').item.json.to || ''; } catch (e) {}
try { const sb = $('Summary bucket').item.json; costId = sb.costPageId || costId; writeError = sb.writeError; } catch (e) {}
try { const s = $('Sum bucket').item.json; summaryLine = 'summary ' + s.bucket.costMonth + ' ' + s.bucket.currency + ': paid ' + s.totalPaid + ', unpaid ' + s.totalUnpaid + ' (' + s.costCount + ' docs)'; } catch (e) {}
if (d.action === 'duplicate' && $json.error) writeError = 'submission count update failed';
const rt = v => ({ rich_text: v ? [{ text: { content: String(v).slice(0, 1900) } }] : [] });
const result = writeError ? 'Error' : d.resultLabel;
const details = [d.resultLabel, 'project: ' + d.projectHow, 'supplier: ' + d.supplierHow, 'key: ' + d.dedupeKey, (d.reviewReasons || []).length ? 'review: ' + d.reviewReasons.join(', ') : '', summaryLine, writeError || '', d.aiError || ''].filter(Boolean).join(' | ');
const props = {
  'Event': { title: [{ text: { content: (result + ' - ' + d.supplierName + ' ' + (d.ref || '')).slice(0, 200) } }] },
  'Processed At': { date: { start: new Date().toISOString() } },
  'Result': { select: { name: result } },
  'Cost': { relation: costId ? [{ id: costId }] : [] },
  'From': { email: d.fromEmail || null },
  'Email Subject': rt(d.emailSubject),
  'Email Message ID': rt(d.gmailId),
  'Details': rt(details),
  'Notified': rt(notified)
};
return { json: { logBody: { parent: { database_id: d.cfg.db.log }, properties: props } } };
